  ('ai:ai-batch-01:f1aacf3bf50e','A1'::public.cefr_level,'grammar','My sister ___ two children.',array['has','is','have','having']::text[],'A','Use ''has'' with he/she/it in the present simple.',array['have_got']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:3a196ead218f','A1'::public.cefr_level,'grammar','___ you like coffee?',array['Does','Do','Is','Are']::text[],'B','Questions in the present simple with ''you'' use ''Do''.',array['present_simple','questions']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:1603f35ee913','A1'::public.cefr_level,'grammar','This is Sara. ___ is my friend.',array['She','He','They','Her']::text[],'A','Use the subject pronoun ''She'' for a woman or girl.',array['pronouns']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:6ec7a5e72424','A1'::public.cefr_level,'grammar','We ___ football on Fridays.',array['are play','play','plays','playing']::text[],'B','Use the base form of the verb with ''we'' in the present simple.',array['present_simple']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
