  ('ai:ai-batch-01:efc24184d4aa','A1'::public.cefr_level,'grammar','Look! The children ___ in the garden.',array['plays','is playing','are playing','play']::text[],'C','Use the present continuous for actions happening now; ''children'' is plural, so ''are''.',array['present_continuous']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
