  ('ai:ai-batch-01:e8b77def1c37','A1'::public.cefr_level,'grammar','I can ___ English.',array['to speak','speaks','speak','speaking']::text[],'C','After ''can'' use the base form of the verb without ''to''.',array['modals']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
