  ('ai:ai-batch-01:671b971e6bd5','B1'::public.cefr_level,'vocabulary','He was ___ of being late again, so he left early.',array['scared at','worried','concerned','afraid']::text[],'D','''Afraid of + -ing'' is the correct pattern; ''worried'' takes ''about''.',array['adjective_prepositions']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:4b85ed950232','B1'::public.cefr_level,'vocabulary','She is very good ___ maths.',array['in','at','on','with']::text[],'B','We say ''good at'' a subject or activity.',array['adjective_prepositions']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:18b456c7f25a','B1'::public.cefr_level,'vocabulary','I ___ my keys. I can''t find them anywhere.',array['have missed','have dropped out','have lost','have run out']::text[],'C','You ''lose'' things you can''t find; ''forget'' is about memory.',array['confusing_words']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:39103d2082a6','B1'::public.cefr_level,'vocabulary','The ___ of living in big cities is very high.',array['fare','cost','price','fee']::text[],'B','The fixed phrase is ''cost of living''.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:9c44cb04c01f','B1'::public.cefr_level,'vocabulary','He gave ___ smoking last year.',array['in','off','up','away']::text[],'C','''Give up'' means stop doing a habit.',array['phrasal_verbs']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:f1f45669e06c','B1'::public.cefr_level,'vocabulary','The weather ___ for tomorrow says it will be sunny.',array['forecast','news','prediction','chart']::text[],'A','''Weather forecast'' is the fixed phrase.',array['collocations','weather']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:54b25997402d','B2'::public.cefr_level,'grammar','If I had known about the traffic, I ___ earlier.',array['will have left','had left','would have left','would leave']::text[],'C','Third conditional: if + past perfect, would have + past participle.',array['conditionals']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:6bcfd77404f1','B2'::public.cefr_level,'grammar','Not only ___ late, but he also forgot the documents.',array['did he was','he is','was he','he was']::text[],'C','After a negative adverbial at the start, invert subject and auxiliary.',array['inversion']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:a7b81d097156','B2'::public.cefr_level,'grammar','She must ___ the train; she isn''t here yet.',array['have missed','missed','has missed','be missed']::text[],'A','''Must have + past participle'' expresses a logical deduction about the past.',array['modals_past']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:f708001ced96','B2'::public.cefr_level,'grammar','I''d rather you ___ smoke in the house.',array['didn''t','not','don''t','won''t']::text[],'A','''Would rather + subject + past simple'' for preferences about others.',array['would_rather']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:dc095c1c4831','B2'::public.cefr_level,'grammar','It''s high time we ___ a decision.',array['make','will make','have made','made']::text[],'D','''It''s (high) time + subject + past simple''.',array['unreal_past']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:54e3f1f6b929','B2'::public.cefr_level,'grammar','By next June, I ___ here for ten years.',array['have worked','am working','will work','will have worked']::text[],'D','Future perfect for actions completed by a future time.',array['future_perfect']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:728fcd84187c','B2'::public.cefr_level,'grammar','He is said ___ a fortune in the 1990s.',array['making','to make','to have made','that he made']::text[],'C','Passive reporting about the past: be said + to have + past participle.',array['passive_reporting']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:889d34c31d12','B2'::public.cefr_level,'grammar','I had my car ___ last week.',array['to service','servicing','serviced','service']::text[],'C','Causative: have + object + past participle.',array['causative']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:790a13fd41aa','B2'::public.cefr_level,'grammar','___ the bad weather, the match went ahead.',array['Despite','In spite','Even though','Although']::text[],'A','''Despite'' is followed by a noun phrase; ''in spite'' needs ''of''.',array['linkers']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:c426d7c37f42','B2'::public.cefr_level,'grammar','Hardly had we sat down ___ the phone rang.',array['as','that','when','then']::text[],'C','''Hardly ... when'' is the fixed pattern.',array['inversion']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:7b784994a5e8','B2'::public.cefr_level,'grammar','She regrets ___ him the truth.',array['not telling','not to tell','don''t tell','to not tell']::text[],'A','''Regret + -ing'' refers to a past action you are sorry about.',array['gerunds']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:91fe30fe1c41','B2'::public.cefr_level,'grammar','Supposing you ___ the lottery, what would you do?',array['have won','will win','win','won']::text[],'D','''Supposing'' works like ''if'' in a second conditional: past simple.',array['conditionals']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:5491779e187b','B2'::public.cefr_level,'vocabulary','The new policy will ___ effect from January.',array['have','come','make','take']::text[],'D','The collocation is ''take effect''.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:a9505ff1438f','B2'::public.cefr_level,'vocabulary','We need to ___ the problem before it gets worse.',array['adopt','address','adapt','admit']::text[],'B','''Address a problem'' means start dealing with it.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:4d9994e5ecc2','B2'::public.cefr_level,'vocabulary','Her argument doesn''t ___ water.',array['hold','keep','take','carry']::text[],'A','''Not hold water'' means not be convincing.',array['idioms']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:c7f4dfc15c11','B2'::public.cefr_level,'vocabulary','The manager ___ down the offer because the salary was too low.',array['turned','let','put','broke']::text[],'A','''Turn down'' means refuse.',array['phrasal_verbs']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:8b0d5d67ea68','B2'::public.cefr_level,'vocabulary','The results were ___ with our predictions.',array['considerate','continual','constant','consistent']::text[],'D','''Consistent with'' means in agreement with.',array['confusing_words']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:1d854a04d2d0','B2'::public.cefr_level,'vocabulary','Prices have risen ___ in the last year.',array['deeply','heavily','sharply','highly']::text[],'C','The natural collocation is ''rise sharply''.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:0cdb77dba989','B2'::public.cefr_level,'vocabulary','I''ll ___ into the matter and call you back.',array['look','see','come','check']::text[],'A','''Look into'' means investigate.',array['phrasal_verbs']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:6df3a4b81f5e','B2'::public.cefr_level,'vocabulary','The project was ___ by a lack of funding.',array['harnessed','heralded','hampered','hallowed']::text[],'C','''Hamper'' means make progress difficult.',array['academic']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:d96f2d6428a7','C1'::public.cefr_level,'grammar','Had I realised the risks, I ___ the contract.',array['would never sign','would never have signed','had never signed','never signed']::text[],'B','Inverted third conditional: Had + subject + past participle, would have + past participle.',array['inversion','conditionals']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:7663cd00cf10','C1'::public.cefr_level,'grammar','Little ___ that the decision would change everything.',array['they knew','they did know','did they know','knew they']::text[],'C','Negative adverbials like ''Little'' at the start trigger inversion with an auxiliary.',array['inversion']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:65e78d0dd042','C1'::public.cefr_level,'grammar','The proposal, ___ was rejected, had taken months to prepare.',array['that','which','what','it']::text[],'B','Non-defining relative clauses use ''which'', not ''that''.',array['relative_clauses']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:8c1afaf6ff7f','C1'::public.cefr_level,'grammar','It is essential that every applicant ___ the form in person.',array['submitted','submits','submit','will submit']::text[],'C','The subjunctive uses the base form after ''essential that''.',array['subjunctive']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:4f326b40eb0e','C1'::public.cefr_level,'grammar','___ to the press, the report would have caused a scandal.',array['Had it been leaked','If it leaked','Having leaked','Was it leaked']::text[],'A','An inverted past conditional matches ''would have caused''.',array['inversion','conditionals']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:01e1d889ffcd','C1'::public.cefr_level,'grammar','What I need ___ a long holiday.',array['being','is','be','are']::text[],'B','In a ''What'' cleft sentence, the ''What'' clause is singular.',array['cleft_sentences']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:8cc8b624df78','C1'::public.cefr_level,'grammar','She would sooner resign ___ accept the new terms.',array['than','to','rather','then']::text[],'A','''Would sooner ... than'' expresses preference.',array['preferences']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:09929c1f8361','C1'::public.cefr_level,'vocabulary','The minister''s comments ___ a heated debate.',array['flashed','burned','sparked','lit']::text[],'C','''Spark a debate'' means cause it to start.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:f0b5c0ca6a7a','C1'::public.cefr_level,'vocabulary','The evidence ___ to the conclusion that the system had failed.',array['directed','showed','pointed','indicated']::text[],'C','The pattern is ''point to a conclusion''; the others don''t take ''to'' here.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:e26ce58e64a2','C1'::public.cefr_level,'vocabulary','He tends to ___ the truth when it suits him.',array['bend','curve','break','fold']::text[],'A','''Bend the truth'' means say something not completely true.',array['idioms']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:198aa3e9f491','C1'::public.cefr_level,'vocabulary','The two studies reached ___ opposed conclusions.',array['horizontally','diametrically','radially','diagonally']::text[],'B','''Diametrically opposed'' is a fixed collocation meaning completely opposite.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:a480611cf300','C1'::public.cefr_level,'vocabulary','Her explanation ___ the issue rather than clarifying it.',array['muddied','brightened','cleared','sharpened']::text[],'A','''Muddy the issue'' means make it less clear, which contrasts with ''clarifying''.',array['idioms']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:9be42aee9815','C1'::public.cefr_level,'vocabulary','The minister ___ the allegations as completely unfounded.',array['discharged','dismissed','dispelled','displaced']::text[],'B','''Dismiss something as ...'' means reject it as not worth considering.',array['verb_patterns']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:9420558eb1bd','C1'::public.cefr_level,'vocabulary','We must ___ a balance between cost and quality.',array['strike','hit','beat','find out']::text[],'A','The collocation is ''strike a balance''.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:40f70658d43e','C1'::public.cefr_level,'vocabulary','The plan was abandoned because it was not financially ___.',array['visible','valid','viable','vital']::text[],'C','''Viable'' means able to work successfully.',array['confusing_words']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:1b8e22d76e19','C2'::public.cefr_level,'grammar','Under no circumstances ___ to leave the building.',array['visitors permitted','are visitors permitted','permitted are visitors','visitors are permitted']::text[],'B','''Under no circumstances'' at the start requires subject-auxiliary inversion.',array['inversion']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:ccb15419c580','C2'::public.cefr_level,'grammar','So severe ___ that the road was closed for a week.',array['did the damage','the damage','the damage was','was the damage']::text[],'D','''So + adjective'' at the start triggers inversion: So severe was the damage...',array['inversion']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:13e525f044cd','C2'::public.cefr_level,'grammar','Were the government ___ taxes, there would be protests.',array['raising','to raise','raise','raised']::text[],'B','Formal inverted conditional: Were + subject + to-infinitive.',array['inversion','conditionals']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:7709cf62f5c4','C2'::public.cefr_level,'grammar','Be that as it ___, we still need a decision today.',array['might be','will','can','may']::text[],'D','''Be that as it may'' is a fixed concessive expression.',array['fixed_expressions']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:3a7617b28719','C2'::public.cefr_level,'grammar','Much ___ I admire her work, I can''t agree with this.',array['so','that','as','though']::text[],'C','''Much as'' means ''although'' (Much as I admire...).',array['concession']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:1bacf54eed69','C2'::public.cefr_level,'grammar','It was not until the 1990s ___ the theory was accepted.',array['that','then','which','since']::text[],'A','Cleft pattern: ''It was not until ... that ...''.',array['cleft_sentences']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:7f5cc5cc8a29','C2'::public.cefr_level,'vocabulary','His speech was full of ___ promises that nobody believed.',array['hollow','vacant','empty-headed','blank']::text[],'A','''Hollow promises'' are insincere ones.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:a3520dfc0b67','C2'::public.cefr_level,'vocabulary','The scandal ___ the party''s chances of winning the election.',array['scattered','scuppered','scrambled','scraped']::text[],'B','''Scupper'' means ruin a plan or chance.',array['advanced_verbs']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:bc7a3cdc552f','C2'::public.cefr_level,'vocabulary','She has a ___ for saying exactly the wrong thing.',array['knock','nick','knot','knack']::text[],'D','''Have a knack for'' means have a natural tendency or skill.',array['idioms']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:5f96a23708ec','C2'::public.cefr_level,'vocabulary','The decision was taken ___, without consulting anyone.',array['unanimously','uniformly','universally','unilaterally']::text[],'D','''Unilaterally'' means by one side only, without others.',array['confusing_words']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:78ebc82fa218','C2'::public.cefr_level,'vocabulary','The author''s style is ___: every word is carefully chosen.',array['nebulous','mediocre','meretricious','meticulous']::text[],'D','''Meticulous'' means very careful and precise.',array['advanced_adjectives']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:3edfd9ffda76','C2'::public.cefr_level,'vocabulary','The two accounts of the event are ___; they cannot both be true.',array['interchangeable','inextricable','irreconcilable','indistinguishable']::text[],'C','''Irreconcilable'' means impossible to make compatible.',array['advanced_adjectives']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:b956ef5f625f','C2'::public.cefr_level,'vocabulary','Critics were quick to ___ holes in the argument.',array['make','pick','cut','dig']::text[],'B','''Pick holes in'' means find faults in.',array['idioms']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:f21d42edfdcb','C2'::public.cefr_level,'vocabulary','The negotiations reached an ___, with neither side willing to compromise.',array['imprint','impact','impulse','impasse']::text[],'D','An ''impasse'' is a situation where no progress is possible.',array['advanced_nouns']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice'),
  ('ai:ai-batch-01:14f15e766896','C2'::public.cefr_level,'vocabulary','His ___ remarks offended almost everyone in the room.',array['tactile','tactical','tactless','tactful']::text[],'C','''Tactless'' means not sensitive to others'' feelings.',array['confusing_words']::text[],'draft','unreviewed','ai-draft:ai-batch-01',null,null,null,null,'practice')
on conflict (external_ref) do update set
  cefr_level = excluded.cefr_level, skill = excluded.skill, prompt = excluded.prompt,
  options = excluded.options, correct_option = excluded.correct_option,
  explanation = excluded.explanation, tags = excluded.tags, passage = excluded.passage,
  media_type = excluded.media_type, media_path = excluded.media_path, media_caption = excluded.media_caption,
  pool = excluded.pool
where public.assessment_questions.status = 'draft' and public.assessment_questions.review_status = 'unreviewed';
